BLUF: Yen's spur-node deviation algorithm enumerates the `K` shortest loopless sustainment routes in strict increasing transit-time order without cycle revisits.

```python
import heapq
from typing import Dict, List, Optional, Set, Tuple

def _dijkstra_avoiding(
    adj: Dict[str, List[Tuple[str, float]]],
    src: str,
    snk: str,
    banned_nodes: Set[str],
    banned_edges: Set[Tuple[str, str]],
) -> Optional[Tuple[float, List[str]]]:
    if src in banned_nodes or snk in banned_nodes:
        return None
    dist: Dict[str, float] = {src: 0.0}
    prev: Dict[str, str] = {}
    pq: List[Tuple[float, str]] = [(0.0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if u == snk:
            path = [u]
            while u in prev:
                u = prev[u]
                path.append(u)
            return d, list(reversed(path))
        if d > dist.get(u, float("inf")):
            continue
        for v, w in adj.get(u, []):
            if v in banned_nodes or (u, v) in banned_edges:
                continue
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))
    return None

def yen_k_shortest_msr_routes(
    roads: List[Tuple[str, str, float]], spod: str, bsa: str, k_routes: int = 4
) -> List[Tuple[float, List[str]]]:
    adj: Dict[str, List[Tuple[str, float]]] = {}
    edge_w: Dict[Tuple[str, str], float] = {}
    for u, v, w in roads:
        adj.setdefault(u, []).append((v, w))
        edge_w[(u, v)] = min(edge_w.get((u, v), float("inf")), w)

    first = _dijkstra_avoiding(adj, spod, bsa, set(), set())
    if first is None:
        return []

    accepted: List[Tuple[float, List[str]]] = [(round(first[0], 4), first[1])]
    cands: List[Tuple[float, List[str]]] = []
    seen_paths: Set[Tuple[str, ...]] = {tuple(first[1])}

    for k in range(1, k_routes):
        prev_path = accepted[k - 1][1]
        for i in range(len(prev_path) - 1):
            spur_node = prev_path[i]
            root_path = prev_path[: i + 1]
            root_cost = sum(edge_w[(root_path[j], root_path[j + 1])] for j in range(len(root_path) - 1))

            banned_e: Set[Tuple[str, str]] = set()
            for _, p in accepted:
                if len(p) > i and p[: i + 1] == root_path:
                    banned_e.add((p[i], p[i + 1]))
            banned_n = set(root_path[:-1])

            spur_res = _dijkstra_avoiding(adj, spur_node, bsa, banned_n, banned_e)
            if spur_res is not None:
                tot_path = root_path[:-1] + spur_res[1]
                ptup = tuple(tot_path)
                if ptup not in seen_paths:
                    seen_paths.add(ptup)
                    heapq.heappush(cands, (round(root_cost + spur_res[0], 4), tot_path))

        if not cands:
            break
        accepted.append(heapq.heappop(cands))
    return accepted
```

ASSESSMENT: Generates instant `K=4` Primary/Alternate/Contingency/Emergency (PACE) route options ranked by road-march duration for movement control teams.

BLUF: Reject non-detections (`cfar_margin_deci_db == 0` or `snr_deci_db < cfar_margin_deci_db`) at the framing boundary before serializing 8 big-endian bytes.
```rust
#[derive(Debug, PartialEq, Eq)]
pub struct CfarHit {
    pub range_bin: u16,
    pub doppler_bin: i16,
    pub snr_deci_db: u16,
    pub cfar_margin_deci_db: u16,
}

pub fn pack_cfar_hit8(h: &CfarHit) -> Result<[u8; 8], &'static str> {
    if h.cfar_margin_deci_db == 0 || h.snr_deci_db < h.cfar_margin_deci_db {
        return Err("invalid cfar detection threshold margin");
    }
    let mut out = [0u8; 8];
    out[0..2].copy_from_slice(&h.range_bin.to_be_bytes());
    out[2..4].copy_from_slice(&h.doppler_bin.to_be_bytes());
    out[4..6].copy_from_slice(&h.snr_deci_db.to_be_bytes());
    out[6..8].copy_from_slice(&h.cfar_margin_deci_db.to_be_bytes());
    Ok(out)
}

pub fn unpack_cfar_hit8(raw: [u8; 8]) -> Result<CfarHit, &'static str> {
    let h = CfarHit {
        range_bin: u16::from_be_bytes([raw[0], raw[1]]),
        doppler_bin: i16::from_be_bytes([raw[2], raw[3]]),
        snr_deci_db: u16::from_be_bytes([raw[4], raw[5]]),
        cfar_margin_deci_db: u16::from_be_bytes([raw[6], raw[7]]),
    };
    if h.cfar_margin_deci_db == 0 || h.snr_deci_db < h.cfar_margin_deci_db {
        return Err("decoded cfar hit violates snr >= margin > 0");
    }
    Ok(h)
}
```
ASSESSMENT: Enforcing `snr >= cfar_margin > 0` stops zero-filled DMA padding tails from spawning false zero-range clutter tracks in radar plot extractors.

BLUF: Lock source and destination `depot_bin_locations` rows in ascending `bin_code` order with `FOR UPDATE`, verify source Condition Code A balance suffices, apply the transfer delta, and append an immutable transfer ledger row.
```sql
CREATE OR REPLACE PROCEDURE transfer_depot_bin_stock(
    p_nsn CHAR(16),
    p_from_bin VARCHAR(24),
    p_to_bin VARCHAR(24),
    p_qty INTEGER,
    p_operator VARCHAR(64)
) LANGUAGE plpgsql AS $$
DECLARE
    v_src_qty INTEGER;
BEGIN
    IF p_qty <= 0 OR p_from_bin = p_to_bin THEN
        RAISE EXCEPTION 'Invalid transfer quantity or identical source/target bins';
    END IF;

    PERFORM 1 FROM depot_bin_locations
    WHERE nsn = p_nsn AND condition_code = 'A' AND bin_code IN (p_from_bin, p_to_bin)
    ORDER BY bin_code ASC
    FOR UPDATE;

    SELECT on_hand_qty INTO v_src_qty
    FROM depot_bin_locations
    WHERE nsn = p_nsn AND condition_code = 'A' AND bin_code = p_from_bin;

    IF v_src_qty IS NULL OR v_src_qty < p_qty THEN
        RAISE EXCEPTION 'Insufficient stock (%) in source bin %', COALESCE(v_src_qty, 0), p_from_bin;
    END IF;

    UPDATE depot_bin_locations SET on_hand_qty = on_hand_qty - p_qty, last_reason_code = 'BIN_XFER_OUT'
    WHERE nsn = p_nsn AND condition_code = 'A' AND bin_code = p_from_bin;

    INSERT INTO depot_bin_locations (bin_code, nsn, condition_code, on_hand_qty, last_reason_code)
    VALUES (p_to_bin, p_nsn, 'A', p_qty, 'BIN_XFER_IN')
    ON CONFLICT (bin_code, nsn, condition_code)
    DO UPDATE SET on_hand_qty = depot_bin_locations.on_hand_qty + EXCLUDED.on_hand_qty,
                  last_reason_code = 'BIN_XFER_IN';

    INSERT INTO depot_bin_transfers (nsn, from_bin, to_bin, qty, moved_by, moved_at)
    VALUES (p_nsn, p_from_bin, p_to_bin, p_qty, p_operator, NOW());
END;
$$;
```
ASSESSMENT: Acquiring `FOR UPDATE` row locks ordered by `bin_code ASC` eliminates `A -> B` vs `B -> A` AB-BA deadlocks when concurrent forklift handhelds consolidate bins.
